    grades = {
        95: 'A+', 90: 'A', 85: 'A-', 80: 'B+', 75: 'B',
        70: 'B-', 65: 'C+', 60: 'C', 55: 'C-', 50: 'D+',
        45: 'D', 40: 'D-'
    }

    for threshold, grade in grades.items():
        if score >= threshold:
            return grade

    return 'F'

